From 6a51bf10d5ee986788c94d3526500bd1c7f7167d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:10:56 +0100
Subject: [PATCH] applet: add an action to mute all other applications

There was no quick way to let a single application play alone, which
is handy when playing music at an event or giving a presentation. Each
playback stream's menu now has an action that mutes all other apps.

BUG: 478834
---
 src/qml/listitemmenu.cpp | 40 +++++++++++++++++++++++++++++++++++++++-
 src/qml/listitemmenu.h   |  2 ++
 2 files changed, 41 insertions(+), 1 deletion(-)

diff --git a/src/qml/listitemmenu.cpp b/src/qml/listitemmenu.cpp
index 631e2cd7..5602e7bf 100644
--- a/src/qml/listitemmenu.cpp
+++ b/src/qml/listitemmenu.cpp
@@ -17,6 +17,7 @@
 #include <KLocalizedString>

 #include <PulseAudioQt/Card>
+#include <PulseAudioQt/Context>
 #include <PulseAudioQt/Device>
 #include <PulseAudioQt/Models>
 #include <PulseAudioQt/Port>
@@ -32,6 +33,8 @@ static const auto s_offProfile = QLatin1String("off");
 ListItemMenu::ListItemMenu(QObject *parent)
     : QObject(parent)
 {
+    connect(Context::instance(), &Context::sinkInputAdded, this, &ListItemMenu::update);
+    connect(Context::instance(), &Context::sinkInputRemoved, this, &ListItemMenu::update);
 }

 ListItemMenu::~ListItemMenu() = default;
@@ -240,7 +243,28 @@ bool ListItemMenu::checkHasContent()
         }
     }

-    return false;
+    return !otherApplicationsSinkInputs().isEmpty();
+}
+
+QList<PulseAudioQt::SinkInput *> ListItemMenu::otherApplicationsSinkInputs() const
+{
+    auto *stream = qobject_cast<PulseAudioQt::SinkInput *>(m_pulseObject.data());
+    if (m_itemType != SinkInput || !stream) {
+        return {};
+    }
+
+    QList<PulseAudioQt::SinkInput *> sinkInputs;
+    const auto allSinkInputs = Context::instance()->sinkInputs();
+    for (auto *sinkInput : allSinkInputs) {
+        if (sinkInput == stream || sinkInput->isVirtualStream()) {
+            continue;
+        }
+        if (stream->client() && sinkInput->client() == stream->client()) {
+            continue;
+        }
+        sinkInputs.append(sinkInput);
+    }
+    return sinkInputs;
 }

 void ListItemMenu::update()
@@ -457,6 +481,20 @@ QMenu *ListItemMenu::createMenu()
         }
     }

+    // Let this application play alone
+    if (const auto otherSinkInputs = otherApplicationsSinkInputs(); !otherSinkInputs.isEmpty()) {
+        auto *muteOthersAction = menu->addAction(QIcon::fromTheme(QStringLiteral("audio-volume-muted")), i18nc("@action:inmenu", "Mute Other Applications"));
+        muteOthersAction->setEnabled(std::any_of(otherSinkInputs.cbegin(), otherSinkInputs.cend(), [](PulseAudioQt::SinkInput *sinkInput) {
+            return !sinkInput->isMuted();
+        }));
+        connect(muteOthersAction, &QAction::triggered, this, [this] {
+            const auto sinkInputs = otherApplicationsSinkInputs();
+            for (auto *sinkInput : sinkInputs) {
+                sinkInput->setMuted(true);
+            }
+        });
+    }
+
     // Choose output / input device
     auto *stream = qobject_cast<PulseAudioQt::Stream *>(m_pulseObject.data());
     if (stream && m_sourceModel && m_sourceModel->rowCount() > 1) {
diff --git a/src/qml/listitemmenu.h b/src/qml/listitemmenu.h
index 5b8d6b54..d3e1c3c7 100644
--- a/src/qml/listitemmenu.h
+++ b/src/qml/listitemmenu.h
@@ -13,6 +13,7 @@

 #include <PulseAudioQt/Models>
 #include <PulseAudioQt/PulseObject>
+#include <PulseAudioQt/SinkInput>

 class QAbstractItemModel;
 class QMenu;
@@ -87,6 +88,7 @@ private:

     void update();
     bool checkHasContent();
+    QList<PulseAudioQt::SinkInput *> otherApplicationsSinkInputs() const;
     QMenu *createMenu();

     bool m_complete = false;
